window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[127]={"id":"127","numero":127,"titre":"Hypertrophie bénigne de la prostate","objectifs":[{"id":"127-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition clinique et l’histoire naturelle de l’hypertrophie bénigne de la prostate (HBP)","contenu":"<p>L'<strong><span class=\"kw-def\">HBP</span></strong> est une <strong><span class=\"kw-def\">hyperplasie bénigne</span></strong> développée au sein de la <strong><span class=\"kw-def\">zone de transition</span></strong> de la prostate (zone centrale entourant le col vésical et l'urètre sous-vésical), responsable d'une <span class=\"kw-clinique\">augmentation du volume de la glande</span>. Histologiquement, c'est un <span class=\"kw-def\">adénomyofibrome</span> (<span class=\"kw-bio\">hyperplasie glandulaire</span> + <span class=\"kw-bio\">hyperplasie stromale</span>, souvent associée à une <span class=\"kw-etio\">inflammation chronique</span>).</p>\n      <table >\n        <thead><tr><th>Trait</th><th>À retenir</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Affection fréquente de l'<strong><span class=\"kw-etio\">homme vieillissant</span></strong> (liée au <span class=\"kw-etio\">vieillissement</span>)</td></tr>\n          <tr><td>Caractère bénin</td><td><strong>Pas de lien démontré</strong> entre HBP et <span class=\"kw-def\">cancer de la prostate</span> (simple association épidémiologique liée à l'âge et au <span class=\"kw-def\">dépistage</span>)</td></tr>\n          <tr><td>Expression latente</td><td>La <strong>majorité</strong> des hommes <span class=\"kw-chiffre\">&gt; 50 ans</span> ont une <span class=\"kw-def\">HBP histologique</span> <strong>asymptomatique</strong>, sans répercussion fonctionnelle</td></tr>\n          <tr><td>Expression symptomatique</td><td>Environ <span class=\"kw-chiffre\">30 %</span> des hommes <span class=\"kw-chiffre\">&gt; 65 ans</span> se plaignent de <strong><span class=\"kw-clinique\">SBAU</span></strong> (symptômes du bas appareil urinaire) liés à l'HBP</td></tr>\n          <tr><td>Mécanisme des symptômes</td><td><strong>Obstruction sous-vésicale</strong> (hypertrophie des lobes prostatiques) ± <strong><span class=\"kw-def\">syndrome d'hyperactivité vésicale</span> réactionnel</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>Aucun parallélisme</strong> entre le <span class=\"kw-clinique\">volume</span> de l'HBP et la <span class=\"kw-clinique\">gravité des SBAU</span> : une grosse prostate peut être asymptomatique, une petite très gênante.</div>\n      <p><strong>Histoire naturelle</strong> — l'<span class=\"kw-clinique\">évolution</span> est aujourd'hui <strong>imprévisible</strong> (stable, progressive ou aggravation brutale). L'obstruction sous-vésicale chronique conduit à la <strong><span class=\"kw-def\">vessie de lutte</span></strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Hypertrophie détrusorienne</span> (épaississement de la paroi vésicale)</li>\n        <li>Puis <span class=\"kw-clinique\">trabéculations</span> et <span class=\"kw-clinique\">diverticules vésicaux</span></li>\n        <li>Au <span class=\"kw-def\">stade</span> ultime : vessie <span class=\"kw-clinique\">distendue, non fonctionnelle</span> → <span class=\"kw-clinique\">rétention chronique indolore</span> avec fuites <strong>par regorgement</strong></li>\n        <li>Complication possible : <span class=\"kw-alerte\">insuffisance rénale chronique obstructive</span> (reflux + dilatation pyélocalicielle bilatérale)</li>\n      </ul>\n      <p><em>Facteurs de progression / de risque de RAU</em> : âge <span class=\"kw-chiffre\">&gt; 60 ans</span>, <span class=\"kw-bio\">PSA sérique</span> <span class=\"kw-chiffre\">&gt; 1,6 ng/mL</span>, <span class=\"kw-clinique\">volume prostatique</span> <span class=\"kw-chiffre\">&gt; 31 mL</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 310 — Tumeur prostate</em></p>","frequence":1},{"id":"127-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique","contenu":"<div class=\"callout callout-info\">✅ <strong><span class=\"kw-def\">Diagnostic positif</span></strong> = <span class=\"kw-clinique\">homme &gt; 50 ans</span> + <span class=\"kw-clinique\">SBAU</span> + <span class=\"kw-clinique\">prostate hypertrophiée au TR</span> + <span class=\"kw-bio\">ECBU normal</span> + <strong>absence d'autre cause</strong>.</div>\n      <p>La maladie repose sur une <strong><span class=\"kw-def\">triade</span></strong> à la relation complexe : <span class=\"kw-clinique\">obstruction sous-vésicale</span> + <span class=\"kw-clinique\">augmentation du volume prostatique</span> + <span class=\"kw-clinique\">SBAU</span>. <span class=\"kw-clinique\">Les</span> trois composantes sont dissociables (grosse prostate sans SBAU, obstruction asymptomatique, hyperactivité vésicale persistant après levée de l'obstacle).</p>\n      <p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-clinique\">SBAU</span></strong> se répartissent en trois phases :</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Symptômes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Remplissage</strong><br><em>(irritatifs)</em></td><td><span class=\"kw-clinique\">Pollakiurie</span> diurne et nocturne ; <span class=\"kw-clinique\">urgenturie</span> ; <span class=\"kw-clinique\">nycturie</span> ; <span class=\"kw-clinique\">incontinence urinaire</span> — un <span class=\"kw-bio\">calendrier mictionnel</span> est justifié surtout si nycturie</td></tr>\n          <tr><td><strong>Mictionnelle</strong> ⭐<br><em>(la plus spécifique)</em></td><td><span class=\"kw-clinique\">Retard d'initiation</span> ; <span class=\"kw-clinique\">dysurie</span> ; <span class=\"kw-clinique\">jet faible</span> ; <span class=\"kw-clinique\">jet haché</span> ; <span class=\"kw-clinique\">miction par poussée abdominale</span> — la <span class=\"kw-bio\">débitmétrie</span> objective la dysurie</td></tr>\n          <tr><td><strong>Post-mictionnelle</strong></td><td><span class=\"kw-clinique\">Gouttes retardataires</span> ; <span class=\"kw-clinique\">sensation de vidange incomplète</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le <strong><span class=\"kw-def\">score IPSS</span></strong> (International Prostate Symptom <span class=\"kw-def\">Score</span>) évalue la sévérité via <span class=\"kw-chiffre\">7 questions</span> ; une <span class=\"kw-chiffre\">8ᵉ question</span> mesure la gêne globale. Il sert aussi à évoquer des diagnostics différentiels ou associés :</p>\n      <ul>\n        <li>SBAU <strong>légers</strong> : IPSS <span class=\"kw-chiffre\">0–7</span></li>\n        <li>SBAU <strong>modérés</strong> : IPSS <span class=\"kw-chiffre\">8–18</span></li>\n        <li>SBAU <strong>sévères</strong> : IPSS <span class=\"kw-chiffre\">19–35</span></li>\n      </ul>\n      <p>Le <strong><span class=\"kw-clinique\">toucher rectal (TR)</span></strong> signe le <span class=\"kw-def\">diagnostic positif</span> d'HBP : glande <strong>augmentée de volume (<span class=\"kw-chiffre\">&gt; 20 g</span>), <span class=\"kw-clinique\">souple</span>, <span class=\"kw-clinique\">indolore</span>, <span class=\"kw-clinique\">lisse</span>, régulière</strong>, avec <span class=\"kw-clinique\">disparition du sillon médian</span> et évasement des bords latéraux. Le bilan initial doit aussi évaluer la <span class=\"kw-clinique\">sexualité</span> (dysfonction érectile/éjaculatoire fréquemment associée).</p>\n      <div class=\"callout callout-danger\">⚠️ <strong>TR évocateur de cancer</strong> (<span class=\"kw-alerte\">nodule dur</span>) : il <strong>n'écarte pas</strong> l'imputation des SBAU à l'HBP (le cancer est asymptomatique sans <span class=\"kw-bio\">envahissement</span>), mais impose des <strong>biopsies prostatiques</strong> <span class=\"kw-alerte\">quel que soit le taux de PSA</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 310 — Tumeur prostate</em></p>","frequence":1,"liens":[{"href":"https://www.urofrance.org/fileadmin/medias/scores/score-IPSS.pdf","label":"Score IPSS (PDF, urofrance)"}]},{"id":"127-3","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les complications aiguës","contenu":"<p><span class=\"kw-clinique\">Les</span> complications aiguës de l'HBP sont des <strong>urgences</strong> 🔥. La plus fréquente est la rétention aiguë d'urine.</p>\n      <div class=\"callout callout-danger\">🔥 <strong><span class=\"kw-alerte\">Rétention aiguë d'urine (RAU)</span></strong> — <span class=\"kw-clinique\">globe vésical</span> <strong><span class=\"kw-clinique\">douloureux</span></strong>, <span class=\"kw-clinique\">besoin impérieux</span> sans miction possible.\n        <ul>\n          <li><strong>Risque</strong> : <span class=\"kw-chiffre\">2 % à 2 ans</span> chez <span class=\"kw-clinique\">les</span> patients ayant des <span class=\"kw-clinique\">SBAU</span> liés à une HBP ; FR = <span class=\"kw-etio\">âge</span> et <span class=\"kw-etio\">sévérité des symptômes</span> (<span class=\"kw-chiffre\">IPSS &gt; 7</span>)</li>\n          <li><strong>Survenue</strong> : spontanée, ou lors d'un événement intercurrent — <span class=\"kw-etio\">fécalome</span>, <span class=\"kw-etio\">anticholinergiques</span>, <span class=\"kw-etio\">anesthésie</span></li>\n          <li><strong>CAT</strong> : <span class=\"kw-clinique\">drainage</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-ttt\">sondage</span> ou <span class=\"kw-ttt\">cathéter sus-pubien</span>)</li>\n        </ul>\n      </div>\n      <table >\n        <thead><tr><th>Complication aiguë</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">Insuffisance rénale aiguë</span> obstructive</strong></td><td>IRA secondaire à une RAU ; <strong>rare</strong> (la douleur fait consulter tôt). Après <span class=\"kw-ttt\">drainage</span> : <span class=\"kw-alerte\">syndrome de levée d'obstacle</span> possible ⚠️ ; la fonction rénale s'améliore rapidement ✅</td></tr>\n          <tr><td><strong>Infections urinaires et urogénitales</strong></td><td>L'HBP favorise <span class=\"kw-etio\">prostatite</span> et <span class=\"kw-etio\">orchi-épididymite</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Hématurie macroscopique</span> initiale</strong></td><td>Liée à la <span class=\"kw-etio\">rupture de petites varices prostatiques</span> ; diagnostic d'élimination — écarter d'abord <span class=\"kw-clinique\">les</span> autres causes d'<span class=\"kw-bio\">hématurie</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-clinique\">Infection urinaire</span> · 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë - anurie · 50 — Pathologie génito-scrotale chez le garçon et chez l'homme</em></p>","frequence":0},{"id":"127-4","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications chroniques","contenu":"<p><span class=\"kw-clinique\">Les</span> complications chroniques résultent de l'obstruction sous-vésicale prolongée et de la <strong><span class=\"kw-def\">vessie de lutte</span></strong>.</p>\n      <table >\n        <thead><tr><th>Complication chronique</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Vessie de lutte</span></strong></td><td><strong>1.</strong> <span class=\"kw-clinique\">Hypertrophie détrusorienne</span> (épaississement pariétal) ; <strong>2.</strong> <span class=\"kw-clinique\">trabéculations</span> et <span class=\"kw-clinique\">diverticules vésicaux</span> ; <strong>3.</strong> <span class=\"kw-def\">stade</span> ultime : vessie <span class=\"kw-clinique\">amincie, distendue, multidiverticulaire</span>, non fonctionnelle</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Rétention vésicale chronique</span></strong></td><td><span class=\"kw-clinique\">Globe indolore</span> le plus souvent, sans besoin d'uriner ; <span class=\"kw-clinique\">incontinence par regorgement</span> ; la pression sur l'hypogastre entraîne l'émission d'urine</td></tr>\n          <tr><td><strong>Hernie de l'aine</strong></td><td>Conséquence des efforts de <span class=\"kw-clinique\">poussée</span> chroniques liés à la dysurie</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Lithiase vésicale</span> de stase</strong></td><td>La stase chronique des urines forme des calculs (mauvaise vidange) → <span class=\"kw-clinique\">hématurie</span> ou <span class=\"kw-etio\">infections récidivantes</span>. Distincte des lithiases rénales (origine métabolique)</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Insuffisance rénale chronique</span> obstructive</strong></td><td><span class=\"kw-imagerie\">Dilatation bilatérale des cavités pyélocalicielles</span> → urétéro-hydronéphrose → <span class=\"kw-imagerie\">amincissement du parenchyme rénal</span>. <strong><span class=\"kw-clinique\">Indolore</span>, installation <span class=\"kw-clinique\">progressive</span></strong> ; récupération <strong>non systématique</strong> après <span class=\"kw-ttt\">drainage</span> ⚠️ (dépend de l'ancienneté)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/bladder-calculus-1","label":"Radiopaedia : Bladder calculus"}]},{"id":"127-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les explorations cliniques pour diagnostiquer une HBP","contenu":"<p>L'exploration clinique repose sur l'<strong>interrogatoire dirigé</strong>, le <strong>TR</strong> et des <strong>outils standardisés</strong>.</p>\n      <table >\n        <thead><tr><th>Exploration clinique</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Interrogatoire dirigé</strong></td><td>Caractériser <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">SBAU</span> (3 phases : remplissage, mictionnelle, post-mictionnelle) et leur retentissement sur la qualité de vie ; évaluer la <span class=\"kw-clinique\">sexualité</span> (questionnaire — dysfonction érectile/éjaculatoire fréquente)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Score IPSS</span></strong></td><td><span class=\"kw-chiffre\">7 questions</span> de sévérité + <span class=\"kw-chiffre\">1 question</span> de gêne ; classe en légers (<span class=\"kw-chiffre\">0–7</span>), modérés (<span class=\"kw-chiffre\">8–18</span>), sévères (<span class=\"kw-chiffre\">19–35</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Toucher rectal (TR)</span></strong></td><td>Glande <span class=\"kw-clinique\">souple</span>, <span class=\"kw-clinique\">indolore</span>, <span class=\"kw-clinique\">lisse</span>, augmentée (<span class=\"kw-chiffre\">&gt; 20 g</span>), avec disparition du sillon médian. <strong>Nécessaire</strong> au bilan initial, <strong>optionnel</strong> pour le <span class=\"kw-def\">suivi</span>. Toute <span class=\"kw-alerte\">induration / nodule</span> → biopsies quel que soit le <span class=\"kw-bio\">PSA</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Calendrier (catalogue) mictionnel</span></strong></td><td>Sur <span class=\"kw-chiffre\">3 jours</span> consécutifs ; recommandé en cas de <span class=\"kw-clinique\">nycturie</span> prédominante ou de SBAU de remplissage prédominants</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Diagnostics différentiels</strong> à évoquer selon la présentation clinique (l'HBP est responsable d'une nycturie dans <span class=\"kw-chiffre\">&lt; 50 %</span> des cas) :</p>\n      <table >\n        <thead><tr><th>Présentation</th><th>Pistes à éliminer</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Nycturie</span> isolée / prédominante</strong></td><td><span class=\"kw-etio\">Troubles du sommeil</span> ; <span class=\"kw-etio\">polyurie des 24 h</span> (<span class=\"kw-etio\">diabète</span> insipide, diabète sucré, potomanie) ; <span class=\"kw-etio\">polyurie nocturne</span> (<span class=\"kw-ttt\">diurétiques</span>, SAHOS, syndrome œdémateux)</td></tr>\n          <tr><td><strong>Phase de <span class=\"kw-clinique\">remplissage</span> prédominante</strong></td><td>Autres causes d'hyperactivité vésicale : <span class=\"kw-etio\">tumeur de vessie</span>, <span class=\"kw-etio\">vessie neurologique</span> (Parkinson, SEP, <span class=\"kw-alerte\">AVC</span>), <span class=\"kw-etio\">calcul / corps étranger</span> de vessie</td></tr>\n          <tr><td><strong>Phase <span class=\"kw-clinique\">mictionnelle</span> / post-mictionnelle</strong></td><td>Autres obstructions sous-vésicales : <span class=\"kw-etio\">sténose de l'urètre</span>, <span class=\"kw-etio\">maladie du col vésical</span> (sujet jeune, petite prostate) ; <span class=\"kw-etio\">hypotonie détrusorienne</span> (âge <span class=\"kw-chiffre\">&gt; 80 ans</span> ou résidu <span class=\"kw-chiffre\">&gt; 300 mL</span>)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 310 — Tumeur prostate · 314 — Tumeur vésicale</em></p>","frequence":0},{"id":"127-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les explorations paracliniques à faire en première intention","contenu":"<p>Le seul examen <strong>systématique</strong> en <span class=\"kw-chiffre\">première intention</span> est l'<strong><span class=\"kw-bio\">ECBU</span></strong> (pour éliminer une <span class=\"kw-clinique\">infection urinaire</span> donnant <span class=\"kw-clinique\">les</span> mêmes symptômes). En milieu spécialisé (urologue), on ajoute la <strong><span class=\"kw-bio\">débitmétrie</span></strong> et la <strong><span class=\"kw-bio\">mesure du résidu post-mictionnel</span></strong>.</p>\n      <p><strong><span class=\"kw-bio\">Débitmétrie urinaire</span></strong> — objective et quantifie la dysurie. Volume uriné <span class=\"kw-chiffre\">&gt; 150 mL</span> nécessaire pour l'interpréter.</p>\n      <ul>\n        <li>Paramètres : <span class=\"kw-bio\">volume uriné</span>, <span class=\"kw-bio\">débit maximal</span>, débit moyen, temps mictionnel</li>\n        <li>Courbe <strong>normale</strong> : en cloche, débit maximal <span class=\"kw-chiffre\">20–30 mL/s</span></li>\n        <li>Courbe <strong>obstructive (HBP)</strong> : aplatie, débit maximal <span class=\"kw-chiffre\">&lt; 15 mL/s</span></li>\n        <li>Ne permet <strong>pas</strong> d'affirmer que l'obstruction est liée à l'HBP (évoquer <span class=\"kw-clinique\">les</span> autres causes, et l'<span class=\"kw-etio\">hypotonie détrusorienne</span> si sujet âgé ou résidu élevé)</li>\n      </ul>\n      <p>Synthèse des examens du bilan initial selon le cadre de prise en charge (HAS 2023) — <em>N = nécessaire, O = optionnel</em> :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Bilan MG</th><th>Bilan urologue</th></tr></thead>\n        <tbody>\n          <tr><td>Interrogatoire SBAU + sexualité</td><td><strong>N</strong></td><td><strong>N</strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Toucher rectal</span></td><td><strong>N</strong></td><td><strong>N</strong></td></tr>\n          <tr><td><span class=\"kw-bio\">Analyse d'urine (ECBU)</span></td><td><strong>N</strong></td><td><strong>N</strong></td></tr>\n          <tr><td><span class=\"kw-bio\">Catalogue mictionnel</span></td><td>O <em>(N si SBAU de remplissage)</em></td><td>O</td></tr>\n          <tr><td><span class=\"kw-bio\">Débitmétrie</span></td><td>—</td><td><strong>N</strong></td></tr>\n          <tr><td><span class=\"kw-bio\">Résidu post-mictionnel</span></td><td>—</td><td><strong>N</strong></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-source\"><em>Tableau transcrit depuis la fiche source (résumé HAS 2023).</em></p>","frequence":1,"liens":[{"href":"https://urologie-chu-bordeaux.fr/service/consultation/la-debitmetrie","label":"Débitmétrie (CHU Bordeaux)"}]},{"id":"127-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les explorations paracliniques à faire selon le contexte","contenu":"<p>Ces examens sont <strong>optionnels</strong>, à demander selon le contexte clinique.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indications &amp; points clés</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">PSA total sérique</span></strong></td><td><span class=\"kw-def\">Dépistage</span> d'un <span class=\"kw-etio\">cancer de la prostate</span> (<strong>individuel, non systématique</strong>). L'HBP élève le <span class=\"kw-bio\">PSA</span> de <span class=\"kw-chiffre\">+ 0,1 ng/mL par gramme</span> ⚠️. Si dépistage indiqué avec <span class=\"kw-bio\">PSA</span> élevé : mesurer la <span class=\"kw-bio\">densité du PSA</span> (suspecte si <span class=\"kw-chiffre\">&gt; 0,15</span>) + la <span class=\"kw-bio\">cinétique</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Créatininémie</span></strong></td><td>Dépiste une <span class=\"kw-alerte\">IRC</span> ; risque d'IRC obstructive <strong>nul</strong> si pas de retentissement vésical</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Échographie réno-vésico-prostatique</span></strong> ⭐</td><td><strong>Rénale</strong> : retentissement haut appareil (<span class=\"kw-imagerie\">dilatation pyélocalicielle</span>, amincissement parenchyme) — non systématique sans retentissement vésical.<br><strong>Vésicale</strong> (sus-pubienne) : <span class=\"kw-imagerie\">hypertrophie détrusorienne</span>, <span class=\"kw-imagerie\">diverticules</span>, <span class=\"kw-imagerie\">lithiase</span>, <span class=\"kw-imagerie\">résidu post-mictionnel</span> (mesurable au Bladder-Scan®).<br><strong>Prostatique</strong> (voie abdominale ou transrectale) : <span class=\"kw-imagerie\">volume</span>, recherche d'un <span class=\"kw-imagerie\">lobe médian</span></td></tr>\n          <tr><td><strong>Endoscopie / urodynamique</strong></td><td><span class=\"kw-imagerie\">Fibroscopie urétrale</span> si suspicion de sténose ; <span class=\"kw-imagerie\">fibroscopie vésicale</span> si ATCD d'<span class=\"kw-bio\">hématurie</span> (éliminer une tumeur).<br><strong><span class=\"kw-bio\">Bilan urodynamique</span></strong> (courbe débit-pression) : distingue obstruction et <span class=\"kw-etio\">hypotonie détrusorienne</span> — si résidu <span class=\"kw-chiffre\">&gt; 300 mL</span>, âge <span class=\"kw-chiffre\">&gt; 80 ans</span> ou sujet <span class=\"kw-chiffre\">&lt; 50 ans</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 310 — Tumeur prostate · 314 — Tumeur vésicale</em></p>","frequence":0},{"id":"127-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement : abstention-surveillance - traitement pharmacologique - traitement chirurgical","contenu":"<p>La prise en charge se gradue selon la gêne et <span class=\"kw-clinique\">les</span> complications : de l'<strong>abstention-<span class=\"kw-def\">surveillance</span></strong> au <strong>traitement pharmacologique</strong> puis <strong>chirurgical</strong>.</p>\n      <table >\n        <thead><tr><th>Stratégie</th><th>Indication</th><th>Moyens</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Abstention-<span class=\"kw-def\">surveillance</span></strong></td><td>HBP non compliquée, SBAU minimes/modérés <strong>sans</strong> altération de la qualité de vie</td><td>Informer et rassurer (caractère bénin). <span class=\"kw-ttt\">RHD</span> : ↓ apports hydriques après <span class=\"kw-chiffre\">18 h</span>, ↓ <span class=\"kw-etio\">caféine</span> et <span class=\"kw-etio\">alcool</span>, traiter une <span class=\"kw-etio\">constipation</span>, arrêt des médicaments favorisant la dysurie (<span class=\"kw-ci\">anticholinergiques</span>, <span class=\"kw-ci\">neuroleptiques</span>)</td></tr>\n          <tr><td><strong>Traitement pharmacologique</strong></td><td>HBP non compliquée, SBAU modérés/sévères <strong>avec</strong> altération de la qualité de vie</td><td><strong>1ʳᵉ intention</strong> : <span class=\"kw-ttt\">α-bloquant</span> ou <span class=\"kw-ttt\">phytothérapie</span>.<br><strong>2ⁿᵈ intention</strong> : <span class=\"kw-ttt\">I5AR</span> (si volume <span class=\"kw-chiffre\">&gt; 40 mL</span>) ; combinaisons <span class=\"kw-ttt\">α-bloquant + I5AR</span> ; <span class=\"kw-ttt\">anticholinergique + α-bloquant</span> (SBAU de remplissage persistants) ; <span class=\"kw-ttt\">IPDE5</span> (si dysfonction érectile)</td></tr>\n          <tr><td><strong>Traitement chirurgical</strong></td><td>SBAU modérés/sévères <strong>résistants</strong> au traitement médical, ou <strong>HBP compliquée</strong></td><td>Voir indications formelles et techniques ci-dessous</td></tr>\n          <tr><td><strong>Traitement palliatif</strong></td><td><span class=\"kw-ci\">Contre-indication</span> opératoire</td><td><span class=\"kw-ttt\">Sonde vésicale</span> / cathéter sus-pubien à demeure, ou <span class=\"kw-ttt\">autosondages</span> intermittents</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-clinique\">Les</span> 5 classes pharmacologiques</strong> :</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Mécanisme &amp; délai</th><th>À retenir / effets indésirables</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">α-bloquants</span></strong></td><td>Relaxation des fibres lisses prostatiques et du col vésical ; effet <strong>rapide</strong> (<span class=\"kw-chiffre\">quelques heures</span>), stable plusieurs années</td><td>Effet <strong>symptomatique seulement</strong> (ne modifie pas l'<span class=\"kw-clinique\">évolution</span>). <span class=\"kw-ttt\">Sevrage</span> de sonde après RAU (ablation à <span class=\"kw-chiffre\">48 h</span>). EI : <span class=\"kw-alerte\">hypotension orthostatique</span> (1ʳᵉ génération), <span class=\"kw-clinique\">troubles éjaculatoires</span> (silodosine). <span class=\"kw-ci\">À interrompre avant chirurgie oculaire</span> (<span class=\"kw-clinique\">syndrome de l</span>'iris flasque)</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Inhibiteurs de la 5α-réductase (I5AR)</span></strong></td><td>Bloquent la conversion testostérone → <span class=\"kw-def\">DHT</span> ; ↓ volume prostatique ~<span class=\"kw-chiffre\">20 %</span> ; délai <strong>plusieurs mois</strong>. Molécules : finastéride, dutastéride</td><td>Préférés si volume <span class=\"kw-chiffre\">&gt; 40 mL</span>. <strong>Seule classe</strong> diminuant le risque de RAU. ↓ le <span class=\"kw-bio\">PSA de 50 %</span> ⭐ (doubler la valeur mesurée). EI : <span class=\"kw-clinique\">baisse de libido</span>, troubles érection/éjaculation, <span class=\"kw-clinique\">gynécomastie</span></td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">IPDE5</span></strong></td><td>↑ GMP cyclique → myorelaxation ; action en <span class=\"kw-chiffre\">quelques jours</span>. Tadalafil <span class=\"kw-chiffre\">5 mg</span> en prise quotidienne (AMM dans l'HBP, <strong>non remboursé</strong>)</td><td>Intérêt si <span class=\"kw-clinique\">dysfonction érectile</span> associée. <span class=\"kw-ci\">CI absolue avec les dérivés nitrés</span> et donneurs de NO (<span class=\"kw-ci\">nicorandil</span>, <span class=\"kw-ci\">molsidomine</span>) — risque d'<span class=\"kw-clinique\">hypotension</span> majeure 🏴‍☠️</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Phytothérapie</span></strong></td><td>Serenoa repens, Pygeum africanum</td><td>Efficacité non démontrée avec fort niveau de preuve ; bonne tolérance, notamment sexuelle</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Anticholinergiques</span></strong></td><td>Inhibent la contraction détrusorienne ; action en <span class=\"kw-chiffre\">quelques semaines</span></td><td>En <strong>association à un α-bloquant</strong> si SBAU de remplissage persistants ; tolérés si résidu <span class=\"kw-chiffre\">&lt; 150 mL</span> ⭐. Surveiller débit et résidu. <span class=\"kw-ci\">CI si glaucome par fermeture de l'angle</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>Indications chirurgicales formelles</strong> ✅ : <span class=\"kw-alerte\">RAU sans sevrage de sonde possible</span> · <span class=\"kw-alerte\">lithiase vésicale</span> · <span class=\"kw-alerte\">IRC obstructive</span> · <span class=\"kw-alerte\">hématurie ou infections récidivantes</span> liées à l'HBP · <span class=\"kw-alerte\">incontinence par regorgement</span>. (Non formelles ❌ : 1ᵉʳ épisode de RAU, d'<span class=\"kw-bio\">hématurie</span> ou d'infection.)</div>\n      <p><strong>Techniques chirurgicales</strong> :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Techniques &amp; particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Ablatifs traditionnels</strong></td><td><strong>RTUP monopolaire</strong> → risque de <span class=\"kw-alerte\">TURP syndrome</span> ⭐ (glycocolle hyperosmolaire → <span class=\"kw-alerte\">surcharge volémique</span> + <span class=\"kw-alerte\">hyponatrémie de dilution</span> ; FR : saignement abondant, durée <span class=\"kw-chiffre\">&gt; 60 min</span>). <strong>Adénomectomie voie haute</strong> (prostates <span class=\"kw-chiffre\">&gt; 80 mL</span>, haut risque <span class=\"kw-etio\">hémorragique</span>)</td></tr>\n          <tr><td><strong>Ablatifs modernes</strong></td><td><strong>RTUP bipolaire</strong> (sérum physiologique → <span class=\"kw-alerte\">pas de TURP syndrome</span>), <strong>vaporisation</strong> et <strong>énucléation endoscopiques</strong> (<span class=\"kw-ttt\">laser</span>/bipolaire) — <span class=\"kw-def\">morbidité</span> immédiate (hémorragie) réduite</td></tr>\n          <tr><td><strong>Non ablatifs / mini-invasifs</strong><br><em>(patient sans lobe médian)</em></td><td><span class=\"kw-ttt\">Incision cervico-prostatique</span> (petit volume <span class=\"kw-chiffre\">&lt; 30–40 mL</span>), implants <span class=\"kw-ttt\">UroLift®</span>, vapeur d'eau <span class=\"kw-ttt\">Rezum®</span>, <span class=\"kw-ttt\">embolisation</span> des artères prostatiques — préservent l'éjaculation (choix chez le sujet jeune)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 <strong>Complication principale</strong> de la <span class=\"kw-ttt\">chirurgie</span> ablative : <span class=\"kw-clinique\">anéjaculation</span> (perte de l'éjaculation antégrade, orgasme préservé) — identique pour toutes <span class=\"kw-clinique\">les</span> techniques ablatives, réduite par les mini-invasives. Risques de <span class=\"kw-clinique\">dysfonction érectile</span> et d'<span class=\"kw-clinique\">incontinence</span> <strong>faibles</strong> (≠ prostatectomie pour cancer).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-clinique\">Infection urinaire</span> · 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë - anurie</em></p>","frequence":2},{"id":"127-9","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les situations justifiant un avis spécialisé","contenu":"<p>L'HBP non compliquée se suit en médecine générale (<span class=\"kw-def\">suivi</span> avant tout <strong>clinique</strong> : symptômes urinaires et sexuels, effets indésirables des traitements). Six situations justifient un <strong>avis spécialisé urologique</strong> selon l'AFU :</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1. SBAU <em>a priori</em> non liés à l'HBP</strong></td><td><span class=\"kw-clinique\">Urgenturies isolées</span> ; <span class=\"kw-clinique\">nycturie isolée</span> ; <span class=\"kw-clinique\">incontinence urinaire</span> ; contexte particulier (maladie neurologique, sténose de l'urètre connue)</td></tr>\n          <tr><td><strong>2. Anomalie à l'examen clinique</strong></td><td><span class=\"kw-alerte\">Globe palpable</span> ; <span class=\"kw-alerte\">nodule ou induration au TR</span> (ou TR non réalisable) ; <span class=\"kw-clinique\">phimosis serré</span></td></tr>\n          <tr><td><strong>3. <span class=\"kw-bio\">ECBU</span> anormal</strong></td><td><span class=\"kw-bio\">Bactériurie</span> ; <span class=\"kw-bio\">leucocyturie</span> ; <span class=\"kw-bio\">hématurie</span></td></tr>\n          <tr><td><strong>4. Traitement médical inefficace</strong></td><td>Avis conseillé <strong>avant</strong> la mise en route d'un <span class=\"kw-ttt\">anticholinergique</span></td></tr>\n          <tr><td><strong>5. <span class=\"kw-bio\">PSA</span> en hausse sous I5AR</strong></td><td>Augmentation du <span class=\"kw-bio\">PSA</span> chez un patient traité par <span class=\"kw-ttt\">I5AR</span> (rappel : l'I5AR ↓ normalement le <span class=\"kw-bio\">PSA</span> de <span class=\"kw-chiffre\">50 %</span>)</td></tr>\n          <tr><td><strong>6. Obstruction sévère / complication</strong></td><td><span class=\"kw-alerte\">Symptômes sévères</span> ; <span class=\"kw-alerte\">RAU</span> ; <span class=\"kw-alerte\">insuffisance rénale obstructive</span> ; <span class=\"kw-alerte\">prostatite aiguë</span> ; <span class=\"kw-alerte\">calcul ou diverticule de vessie</span> ; résidu post-mictionnel <span class=\"kw-chiffre\">&gt; 100 mL</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë - anurie · 264 — Insuffisance rénale chronique</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> :</strong> la <span class=\"kw-alerte\">rétention aiguë d'urine (RAU)</span>, complication aiguë imposant un <span class=\"kw-ttt\">drainage vésical</span> sans délai.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">drainage vésical</span> (sondage urétral ou <span class=\"kw-ttt\">cathéter sus-pubien</span>), puis <span class=\"kw-ttt\">α-bloquant</span> avec tentative d'ablation de la sonde à <span class=\"kw-chiffre\">48 h</span> (récidive ≈ <span class=\"kw-chiffre\">50 %</span>).<br><strong>Facteurs déclenchants :</strong> <span class=\"kw-etio\">fécalome</span>, <span class=\"kw-ci\">anticholinergiques</span>, anesthésie.<br><strong>Après <span class=\"kw-ttt\">drainage</span> :</strong> surveiller le <span class=\"kw-alerte\">syndrome de levée d'obstacle</span> en cas d'<span class=\"kw-etio\">insuffisance rénale aiguë obstructive</span>.</p>","hospit":"<p><strong>Ambulatoire :</strong> prise en charge initiale en <span class=\"kw-ttt\">médecine générale</span> (interrogatoire des SBAU et de la sexualité, <span class=\"kw-clinique\">toucher rectal</span>, <span class=\"kw-bio\">ECBU</span>).<br><strong>Avis spécialisé (urologue) si :</strong> SBAU a priori non liés à l'HBP (<span class=\"kw-clinique\">urgenturie</span>, <span class=\"kw-clinique\">nycturie</span> ou <span class=\"kw-clinique\">incontinence</span> isolées, contexte neurologique), anomalie clinique (<span class=\"kw-clinique\">nodule au TR</span>, <span class=\"kw-alerte\">globe palpable</span>, phimosis serré), <span class=\"kw-bio\">ECBU anormal</span>, échec du traitement médical.<br><strong>Complication / obstruction sévère :</strong> symptômes sévères, <span class=\"kw-alerte\">RAU</span>, <span class=\"kw-alerte\">insuffisance rénale obstructive</span>, <span class=\"kw-etio\">prostatite aiguë</span>, calcul ou <span class=\"kw-clinique\">diverticule</span> de vessie, <span class=\"kw-chiffre\">résidu post-mictionnel > 100 mL</span>.<br><strong>Patients sous I5AR :</strong> avis si <span class=\"kw-bio\">augmentation du PSA</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Rétention aiguë d'urine</span> : globe vésical douloureux, <span class=\"kw-alerte\">urgence</span> imposant un <span class=\"kw-ttt\">drainage vésical</span>.</li><li><span class=\"kw-alerte\">Insuffisance rénale aiguë obstructive</span> (RAU négligée) → risque de <span class=\"kw-alerte\">syndrome de levée d'obstacle</span> après <span class=\"kw-ttt\">drainage</span>.</li><li><span class=\"kw-alerte\">Hématurie macroscopique</span> : éliminer <span class=\"kw-clinique\">les</span> autres étiologies avant d'imputer l'HBP.</li><li><span class=\"kw-etio\">Prostatite</span> ou <span class=\"kw-etio\">orchi-épididymite</span> favorisée par l'HBP.</li><li><span class=\"kw-clinique\">Nodule dur, pierreux, irrégulier au toucher rectal</span> → <span class=\"kw-ttt\">biopsies prostatiques</span> quel que soit le <span class=\"kw-bio\">PSA</span>.</li><li><span class=\"kw-alerte\">Insuffisance rénale chronique obstructive</span> : <span class=\"kw-radio\">dilatation bilatérale des cavités pyélocalicielles</span>, <span class=\"kw-radio\">amincissement du parenchyme rénal</span>.</li><li><span class=\"kw-etio\">Lithiase vésicale de stase</span>, <span class=\"kw-clinique\">incontinence par regorgement</span>, <span class=\"kw-chiffre\">résidu post-mictionnel > 100 mL</span>.</li></ul>","principes":"<p>Choix guidé par la <span class=\"kw-chiffre\">sévérité des SBAU (score IPSS)</span>, le retentissement sur la qualité de vie et la présence de <span class=\"kw-alerte\">complications</span>.</p><p><strong>Abstention-<span class=\"kw-def\">surveillance</span></strong></p><ul><li>Indication : HBP non compliquée, <span class=\"kw-chiffre\">SBAU minimes à modérés (IPSS 0-7)</span> sans altération de la qualité de vie.</li><li>Informer et <span class=\"kw-ttt\">rassurer</span> sur le caractère bénin de l'HBP.</li><li><span class=\"kw-ttt\">Règles hygiéno-diététiques</span> : <span class=\"kw-ttt\">réduction</span> des apports hydriques après <span class=\"kw-chiffre\">18 h</span>, diminution <span class=\"kw-ttt\">caféine</span> et <span class=\"kw-ttt\">alcool</span>, traitement d'une <span class=\"kw-etio\">constipation</span>.</li><li><span class=\"kw-ttt\">Arrêt des médicaments favorisant la dysurie</span> (<span class=\"kw-ci\">anticholinergiques</span>, <span class=\"kw-ci\">neuroleptiques</span>).</li></ul><p><strong>Traitement pharmacologique — 1re intention</strong></p><p><span class=\"kw-def\">Réévaluation</span> à<span class=\"kw-chiffre\"> 6 semaines</span>.</p><ul><li>Indication : <span class=\"kw-chiffre\">SBAU modérés à sévères (IPSS ≥ 8)</span> avec altération de la qualité de vie.</li><li><span class=\"kw-ttt\">α-bloquant</span> : relaxation des fibres musculaires lisses de la prostate et du col, efficace en <span class=\"kw-chiffre\">quelques heures</span> ; effet uniquement symptomatique (ne modifie pas l'<span class=\"kw-clinique\">évolution</span>).</li><li><span class=\"kw-ttt\">Phytothérapie</span> (Serenoa repens, Pygeum africanum) : bien tolérée, efficacité de faible niveau de preuve.</li><li>EI des α-bloquants : <span class=\"kw-alerte\">hypotension orthostatique</span>, <span class=\"kw-etio\">troubles de l'éjaculation</span> ; <span class=\"kw-ci\">à interrompre avant une chirurgie de la cataracte</span> (<span class=\"kw-clinique\">syndrome de l</span>'iris flasque).</li></ul><p><strong>Traitement pharmacologique — <span class=\"kw-chiffre\">2e intention</span></strong></p><ul><li><span class=\"kw-ttt\">Inhibiteur de la 5α-réductase (finastéride, dutastéride)</span> : diminue le volume prostatique d'environ <span class=\"kw-chiffre\">20 %</span>, action en <span class=\"kw-chiffre\">plusieurs mois</span> ; préférentiel si <span class=\"kw-chiffre\">volume prostatique > 40 mL</span>.</li><li>I5AR : seule classe qui <span class=\"kw-ttt\">diminue le risque de RAU</span> ; abaisse le <span class=\"kw-bio\">PSA de 50 %</span> (à doubler pour interpréter un <span class=\"kw-def\">dépistage</span>).</li><li>Association <span class=\"kw-ttt\">α-bloquant + I5AR</span> si monothérapie inefficace.</li><li>Association <span class=\"kw-ttt\">anticholinergique + α-bloquant</span> si SBAU de remplissage persistants (<span class=\"kw-chiffre\">RPM < 150 mL</span>).</li><li><span class=\"kw-ttt\">IPDE5</span> (tadalafil) si <span class=\"kw-etio\">dysfonction érectile</span> associée ; <span class=\"kw-ci\">contre-indiqué avec les dérivés nitrés et donneurs de NO</span> (nicorandil, molsidomine).</li></ul><p><strong>Traitement chirurgical</strong></p><p><span class=\"kw-bio\">ECBU</span> obligatoire avant tout geste ; traiter une bactériurie.</p><ul><li>Indication : SBAU modérés/sévères <span class=\"kw-ttt\">résistants au traitement médical</span> ou HBP compliquée.</li><li>Indications formelles : <span class=\"kw-alerte\">RAU sans sevrage de sonde possible</span>, <span class=\"kw-etio\">lithiase vésicale</span>, <span class=\"kw-alerte\">IRC obstructive</span>, <span class=\"kw-bio\">hématurie</span> ou infections récidivantes, <span class=\"kw-clinique\">incontinence par regorgement</span>.</li><li>Techniques : <span class=\"kw-ttt\">RTUP monopolaire</span> (risque de <span class=\"kw-alerte\">TURP syndrome</span>) ou <span class=\"kw-ttt\">bipolaire</span>, <span class=\"kw-ttt\">énucléation/vaporisation endoscopique</span>, <span class=\"kw-ttt\">adénomectomie voie haute</span> si volume <span class=\"kw-chiffre\">> 80 mL</span>.</li><li>Complication principale : <span class=\"kw-etio\">anéjaculation</span>, à accepter par le patient.</li></ul><p><strong>Traitement palliatif</strong></p><ul><li>Réservé aux patients avec <span class=\"kw-ci\">contre-indication opératoire</span>.</li><li><span class=\"kw-ttt\">Sonde vésicale à demeure</span> ou <span class=\"kw-ttt\">cathéter sus-pubien</span>, ou <span class=\"kw-ttt\">autosondages intermittents</span>.</li></ul>","suivi":"<p><strong>Nature :</strong> <span class=\"kw-def\">suivi</span> avant tout <span class=\"kw-clinique\">clinique</span> (symptômes urinaires et sexuels, effets indésirables) ; <span class=\"kw-clinique\">TR</span>, catalogue mictionnel, <span class=\"kw-imagerie\">débitmétrie</span> et résidu post-mictionnel optionnels.<br><strong>Sous α-bloquant :</strong> <span class=\"kw-def\">réévaluation</span> précoce à <span class=\"kw-chiffre\">6 semaines</span>.<br><strong>Sous I5AR :</strong> réévaluation à <span class=\"kw-chiffre\">12 semaines</span> ; <span class=\"kw-bio\">dosage annuel du PSA</span>.<br><strong>Après <span class=\"kw-ttt\">chirurgie</span> :</strong> vérifier l'absence de complication à <span class=\"kw-chiffre\">6 semaines</span>, évaluer l'efficacité à partir de <span class=\"kw-chiffre\">3 mois</span>.</p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-10-item-127-hypertrophie-benigne-de-la-prostate/","label":"Collège d'Urologie — référentiel item 127 (chap. 10)"},{"href":"https://radiopaedia.org/articles/benign-prostatic-hyperplasia","label":"Radiopaedia : Benign prostatic hyperplasia"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"HBP confirmée avec SBAU — Homme > 50 ans · TR : prostate souple augmentée · ECBU normal · pas d'autre cause","detail":"<h4>CAT — SBAU liés à une hypertrophie bénigne de la prostate — Orientation thérapeutique selon <span class=\"kw-clinique\">les</span> complications et la sévérité (<span class=\"kw-def\">score</span> IPSS)</h4>","branches":[{"to":"q-grav","label":"Diagnostic posé","color":"blue"}]},{"id":"q-grav","kind":"decision","label":"Complication aiguë ou indication chirurgicale formelle ? — RAU, IRC obstructive, lithiase vésicale, hématurie ou infections récidivantes, incontinence par regorgement","branches":[{"to":"t-urg","label":"Oui","color":"red"},{"to":"q-sbau","label":"Non","color":"green"}]},{"id":"t-urg","kind":"terminal","label":"Urgence / traitement chirurgical","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">RAU</span> : <span class=\"kw-ttt\">drainage vésical</span> en <span class=\"kw-alerte\">urgence</span> (sondage ou cathéter sus-pubien)</li><li><span class=\"kw-ttt\">Sevrage</span> de sonde sous <span class=\"kw-ttt\">α-bloquant</span>, tentative d'ablation à <span class=\"kw-chiffre\">48 h</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">RTUP monopolaire/bipolaire</span>, énucléation ou vaporisation endoscopique</li><li><span class=\"kw-ttt\">Adénomectomie voie haute</span> si volume <span class=\"kw-chiffre\">> 80 mL</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">ECBU</span> avant tout geste chirurgical (traiter une bactériurie)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Risque de <span class=\"kw-alerte\">syndrome de levée d'obstacle</span> après <span class=\"kw-ttt\">drainage</span></li></ul>"},{"id":"q-sbau","kind":"decision","label":"SBAU modérés/sévères avec altération de la qualité de vie ? — Évaluation par le score IPSS","branches":[{"to":"t-abst","label":"Non (IPSS 0-7, QdV conservée)","color":"green"},{"to":"t-pharm","label":"Oui (IPSS ≥ 8)","color":"amber"}]},{"id":"t-abst","kind":"terminal","label":"Abstention-surveillance + règles hygiéno-diététiques","color":"green","detail":"<h4>Conduite</h4><ul><li>Informer et <span class=\"kw-ttt\">rassurer</span> sur le caractère bénin de l'HBP</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Réduction</span> des apports hydriques après <span class=\"kw-chiffre\">18 h</span></li><li>Diminution <span class=\"kw-ttt\">caféine</span> et <span class=\"kw-ttt\">alcool</span>, traiter une <span class=\"kw-etio\">constipation</span></li><li><span class=\"kw-ci\">Arrêt des médicaments favorisant la dysurie</span> (anticholinergiques, neuroleptiques)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Suivi</span> <span class=\"kw-clinique\">clinique</span></li></ul>"},{"id":"t-pharm","kind":"terminal","label":"Traitement pharmacologique","color":"amber","detail":"<h4>Traitement</h4><ul><li>1re intention : <span class=\"kw-ttt\">α-bloquant</span> (efficace en quelques heures) ou <span class=\"kw-ttt\">phytothérapie</span></li><li><span class=\"kw-chiffre\">2e intention</span> : <span class=\"kw-ttt\">I5AR</span> si <span class=\"kw-chiffre\">volume > 40 mL</span>, ou association <span class=\"kw-ttt\">α-bloquant + I5AR</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Anticholinergique + α-bloquant</span> si SBAU de remplissage persistants (RPM < 150 mL)</li><li><span class=\"kw-ttt\">IPDE5</span> si <span class=\"kw-etio\">dysfonction érectile</span> associée</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> à <span class=\"kw-chiffre\">6 semaines</span> (α-bloquant) / <span class=\"kw-chiffre\">12 semaines</span> (I5AR)</li><li>Échec du traitement médical bien conduit → <span class=\"kw-ttt\">avis chirurgical</span></li></ul>"}]},"cards":[{"i":"27c0bc05323c","n":127,"o":"127-1","u":"Définition","t":"Connaître la définition clinique et l’histoire naturelle de l’hypertrophie bénigne de la prostate (HBP)","q":"Quelles sont les complications de l'hypertrophie bénigne de la prostate (HBP) non ou mal traitée ?","a":"<p>L'HBP, si elle n'est pas traitée, peut entraîner une <strong>vessie de lutte</strong> avec :</p><ul><li>Hypertrophie détrusorienne,</li><li>Trabéculations et diverticules vésicaux,</li><li>Au stade ultime, une vessie distendue non fonctionnelle (avec rétention chronique indolore et fuites par regorgement).</li></ul><p>Une complication grave est l'<strong>insuffisance rénale chronique obstructive</strong>, secondaire à un reflux urinaire et une dilatation pyélocalicielle bilatérale.</p>"},{"i":"6d2eee7cd616","n":127,"o":"127-1","u":"Définition","t":"Connaître la définition clinique et l’histoire naturelle de l’hypertrophie bénigne de la prostate (HBP)","q":"Quel est le devenir des symptômes du bas appareil urinaire (SBAU) liés à l'HBP ?","a":"<p>L'évolution des SBAU liés à l'HBP est <strong>imprévisible</strong>, pouvant rester stable, progresser ou s'aggraver brutalement. Ils peuvent entraîner une <strong>obstruction sous-vésicale chronique</strong> et un syndrome d'hyperactivité vésicale réactionnel, sans parallélisme avec le volume prostatique.</p>"},{"i":"897f9c2c5af1","n":127,"o":"127-1","u":"Définition","t":"Connaître la définition clinique et l’histoire naturelle de l’hypertrophie bénigne de la prostate (HBP)","q":"Quels sont les facteurs de progression de l'hypertrophie bénigne de la prostate (HBP) ou de risque de rétention aiguë d'urine (RAU) ?","a":"<p>Les facteurs de progression de l'HBP ou de risque de RAU sont :</p><ul><li>L'<strong>âge > 60 ans</strong>,</li><li>Un <strong>PSA sérique > 1,6 ng/mL</strong>,</li><li>Un <strong>volume prostatique > 31 mL</strong>.</li></ul>"},{"i":"bb423aa47ed7","n":127,"o":"127-1","u":"Définition","t":"Connaître la définition clinique et l’histoire naturelle de l’hypertrophie bénigne de la prostate (HBP)","q":"Quelle est la définition clinique et histologique de l'hypertrophie bénigne de la prostate (HBP) ?","a":"<p>L'HBP est une <strong>hyperplasie bénigne</strong> de la prostate, développée au sein de la <strong>zone de transition</strong>. Elle est responsable d'une augmentation du volume de la glande. Histologiquement, il s'agit d'un <strong>adénomyofibrome</strong>, associant une hyperplasie glandulaire et stromale, souvent liée à une inflammation chronique.</p>"},{"i":"39add70d5a4f","n":127,"o":"127-2","u":"Diagnostic positif","t":"Connaître la démarche diagnostique","q":"Comment évalue-t-on la sévérité des SBAU dans le cadre d'une hypertrophie bénigne de la prostate ?","a":"<p>La sévérité des SBAU est évaluée par le score <strong>IPSS (International Prostate Symptom Score)</strong>. Ce questionnaire comporte 7 questions sur les symptômes et une 8<sup>e</sup> question sur la gêne globale. Les seuils sont :</p><ul><li><strong>SBAU légers</strong> : IPSS 0–7</li><li><strong>SBAU modérés</strong> : IPSS 8–18</li><li><strong>SBAU sévères</strong> : IPSS 19–35</li></ul>"},{"i":"68f534c2a02e","n":127,"o":"127-2","u":"Diagnostic positif","t":"Connaître la démarche diagnostique","q":"Quelle est la définition clinique de l'hypertrophie bénigne de la prostate (HBP) pour établir un diagnostic positif ?","a":"<p>Le diagnostic positif de l'HBP repose sur l'association chez un <strong>homme de plus de 50 ans</strong> de <strong>symptômes du bas appareil urinaire (SBAU)</strong>, d'une <strong>prostate hypertrophiée au toucher rectal</strong>, d'un <strong>ECBU normal</strong>, et de l'<strong>absence d'autre cause</strong> des SBAU.</p>"},{"i":"ac9a0edfc65a","n":127,"o":"127-2","u":"Diagnostic positif","t":"Connaître la démarche diagnostique","q":"Quels sont les principaux types de symptômes du bas appareil urinaire (SBAU) et leurs manifestations dans l'hypertrophie bénigne de la prostate ?","a":"<ul><li><strong>Symptômes de remplissage (irritatifs)</strong> : pollakiurie diurne et nocturne, urgenturie, nycturie, incontinence urinaire. Un calendrier mictionnel est utile pour les objectiver, surtout en cas de nycturie.</li><li><strong>Symptômes mictionnels (obstructifs)</strong> : retard à l'initiation, dysurie, jet faible, jet haché, miction par poussée abdominale. Ces signes sont les plus spécifiques. Une débitmétrie est utile pour objectiver la dysurie.</li><li><strong>Symptômes post-mictionnels</strong> : gouttes retardataires, sensation de vidange incomplète.</li></ul>"},{"i":"d739b7d3f7a3","n":127,"o":"127-2","u":"Diagnostic positif","t":"Connaître la démarche diagnostique","q":"Quels sont les éléments caractéristiques de l'hypertrophie bénigne de la prostate au toucher rectal (TR) ?","a":"<p>Le toucher rectal révèle une glande <strong>augmentée de volume (> 20 g)</strong>, <strong>souple</strong>, <strong>indolore</strong>, <strong>lisse</strong>, <strong>régulière</strong>, avec une <strong>disparition du sillon médian</strong> et un <strong>évasement des bords latéraux</strong>.</p>"},{"i":"dc04c0da1370","n":127,"o":"127-2","u":"Diagnostic positif","t":"Connaître la démarche diagnostique","q":"Quand un toucher rectal est-il évocateur de cancer de la prostate et quelle est la conduite à tenir ?","a":"<p>Un toucher rectal est évocateur de cancer de la prostate s'il révèle un <strong>nodule dur</strong>. Dans ce cas, des <strong>biopsies prostatiques</strong> sont impératives, <strong>quel que soit le taux de PSA</strong>, même si cela n'écarte pas l'imputation des SBAU à l'HBP (le cancer étant initialement asymptomatique sans envahissement).</p>"},{"i":"2c549afd64d6","n":127,"o":"127-3","u":"Identifier une urgence","t":"Connaître les complications aiguës","q":"Outre la rétention aiguë d'urine, quelles autres complications aiguës de l'hypertrophie bénigne de la prostate doivent être connues ?","a":"<p>Les autres complications aiguës de l'HBP comprennent :</p><ul><li>L'<strong>insuffisance rénale aiguë obstructive</strong>, généralement secondaire à une RAU et qui régresse rapidement après drainage.</li><li>Les <strong>infections urinaires et urogénitales</strong>, telles que la prostatite ou l'orchi-épididymite.</li><li>L'<strong>hématurie macroscopique initiale</strong>, liée à la rupture de petites varices prostatiques, qui est un diagnostic d'élimination.</li></ul>"},{"i":"40b18d327a82","n":127,"o":"127-3","u":"Identifier une urgence","t":"Connaître les complications aiguës","q":"Quels sont les facteurs de risque et les circonstances de survenue d'une rétention aiguë d'urine (RAU) dans le contexte d'une HBP ?","a":"<p>Les facteurs de risque de RAU sont :</p><ul><li>L'<strong>âge</strong>.</li><li>La <strong>sévérité des symptômes</strong> du bas appareil urinaire (SBAU) liés à l'HBP, notamment un score IPSS &gt; 7.</li></ul><p>La RAU peut survenir spontanément ou lors d'un événement intercurrent tel qu'un <strong>fécalome</strong>, la prise d'<strong>anticholinergiques</strong> ou une <strong>anesthésie</strong>.</p>"},{"i":"a3d96fc0ebad","n":127,"o":"127-3","u":"Identifier une urgence","t":"Connaître les complications aiguës","q":"Quelle est la complication aiguë la plus fréquente de l'hypertrophie bénigne de la prostate (HBP) et comment se manifeste-t-elle cliniquement ?","a":"<p>La complication aiguë la plus fréquente de l'HBP est la <strong>rétention aiguë d'urine (RAU)</strong>.</p><ul><li>Elle se manifeste par un <strong>globe vésical douloureux</strong>.</li><li>Le patient présente un <strong>besoin impérieux</strong> d'uriner, mais sans miction possible.</li></ul>"},{"i":"d9bf25d0a7cc","n":127,"o":"127-3","u":"Identifier une urgence","t":"Connaître les complications aiguës","q":"Quelle est la conduite à tenir immédiate devant une rétention aiguë d'urine (RAU) due à une HBP ?","a":"<p>Devant une RAU, la conduite à tenir immédiate est un <strong>drainage en urgence</strong> des urines. Cela peut être réalisé par un <strong>sondage vésical</strong> ou la pose d'un <strong>cathéter sus-pubien</strong>.</p>"},{"i":"21dd9141b0a4","n":127,"o":"127-5","u":"Diagnostic positif","t":"Connaître les explorations cliniques pour diagnostiquer une HBP","q":"Quel est l'objectif de l'interrogatoire dirigé dans le diagnostic de l'HBP ?","a":"<p>L'interrogatoire dirigé vise à :</p><ul><li>Caractériser les <strong>Symptômes du Bas Appareil Urinaire (SBAU)</strong> selon leurs <strong>trois phases</strong> (remplissage, mictionnelle, post-mictionnelle) et évaluer leur <strong>retentissement sur la qualité de vie</strong>.</li><li>Évaluer la <strong>sexualité</strong>, notamment la présence de dysfonction érectile ou éjaculatoire, qui est fréquente.</li></ul>"},{"i":"28b8bc85593c","n":127,"o":"127-5","u":"Diagnostic positif","t":"Connaître les explorations cliniques pour diagnostiquer une HBP","q":"Quel est le rôle du toucher rectal (TR) dans le diagnostic de l'HBP et que doit-il rechercher ?","a":"<p>Le toucher rectal est indispensable au bilan initial de l'HBP pour évaluer la prostate. Il recherchera :</p><ul><li>Une glande <strong>souple</strong>, <strong>indolore</strong>, <strong>lisse</strong>.</li><li>Une augmentation de volume (estimée à <strong>plus de 20 g</strong>).</li><li>La <strong>disparition du sillon médian</strong>.</li></ul><p>Toute <strong>induration ou nodule</strong> impose des biopsies, quel que soit le taux de PSA.</p>"},{"i":"4a236010488e","n":127,"o":"127-5","u":"Diagnostic positif","t":"Connaître les explorations cliniques pour diagnostiquer une HBP","q":"Quel outil standardisé permet d'évaluer la sévérité des symptômes lors du diagnostic de l'HBP ?","a":"<p>Le <strong>Score IPSS (International Prostate Symptom Score)</strong> est l'outil standardisé utilisé. Il comporte <strong>7 questions de sévérité</strong> et <strong>1 question de gêne</strong>, permettant de classer les SBAU en :</p><ul><li>Légers (<strong>0-7</strong>)</li><li>Modérés (<strong>8-18</strong>)</li><li>Sévères (<strong>19-35</strong>)</li></ul>"},{"i":"699430681e97","n":127,"o":"127-5","u":"Diagnostic positif","t":"Connaître les explorations cliniques pour diagnostiquer une HBP","q":"Dans quels cas spécifiques un calendrier mictionnel est-il recommandé lors du diagnostic de l'HBP ?","a":"<p>Un calendrier mictionnel (réalisé sur <strong>3 jours consécutifs</strong>) est recommandé en cas de :</p><ul><li><strong>Nycturie prédominante</strong>.</li><li><strong>SBAU de remplissage prédominants</strong>.</li></ul>"},{"i":"94826d8ea92f","n":127,"o":"127-5","u":"Diagnostic positif","t":"Connaître les explorations cliniques pour diagnostiquer une HBP","q":"Quelle est l'exploration clinique initiale de l'hypertrophie bénigne de la prostate (HBP) ?","a":"<p>L'exploration clinique initiale de l'HBP repose sur :</p><ul><li>Un <strong>interrogatoire dirigé</strong></li><li>Le <strong>toucher rectal (TR)</strong></li><li>Des <strong>outils standardisés</strong></li></ul>"},{"i":"2d96aced1777","n":127,"o":"127-9","u":"Suivi et/ou pronostic","t":"Connaître les situations justifiant un avis spécialisé","q":"Quelles anomalies à l'ECBU chez un patient avec hypertrophie bénigne de la prostate (HBP) nécessitent un avis urologique ?","a":"<p>Un avis urologique est indiqué si l'ECBU révèle :</p><ul><li>Une <strong>bactériurie</strong>.</li><li>Une <strong>leucocyturie</strong>.</li><li>Une <strong>hématurie</strong>.</li></ul>"},{"i":"84ee31579761","n":127,"o":"127-9","u":"Suivi et/ou pronostic","t":"Connaître les situations justifiant un avis spécialisé","q":"Quelles anomalies à l'examen clinique chez un patient avec hypertrophie bénigne de la prostate (HBP) imposent un avis urologique ?","a":"<p>Un avis urologique est nécessaire en cas de :</p><ul><li><strong>Globe vésical palpable</strong>.</li><li>Présence d'un <strong>nodule</strong> ou d'une <strong>induration</strong> lors du toucher rectal (TR), ou si le <strong>TR n'est pas réalisable</strong>.</li><li><strong>Phimosis serré</strong>.</li></ul>"},{"i":"cf0dc26d293d","n":127,"o":"127-9","u":"Suivi et/ou pronostic","t":"Connaître les situations justifiant un avis spécialisé","q":"Quand faut-il référer un patient avec hypertrophie bénigne de la prostate (HBP) pour un avis urologique en lien avec le traitement médical ?","a":"<p>Un avis urologique est justifié si :</p><ul><li>Le <strong>traitement médical est inefficace</strong>.</li><li>Il est envisagé de prescrire un <strong>anticholinergique</strong>.</li><li>Le <strong>PSA augmente</strong> chez un patient traité par <strong>inhibiteur de la 5α-réductase (I5AR)</strong>, car l'I5AR doit normalement diminuer le PSA d'environ 50 %.</li></ul>"},{"i":"f118f52dcbb9","n":127,"o":"127-9","u":"Suivi et/ou pronostic","t":"Connaître les situations justifiant un avis spécialisé","q":"Quelles situations d'obstruction sévère ou de complications de l'hypertrophie bénigne de la prostate (HBP) justifient un avis urologique ?","a":"<p>Un avis urologique urgent est requis en cas de :</p><ul><li><strong>Symptômes urinaires sévères</strong>.</li><li><strong>Rétention aiguë d'urine (RAU)</strong>.</li><li><strong>Insuffisance rénale obstructive</strong>.</li><li><strong>Prostatite aiguë</strong>.</li><li>Présence de <strong>calcul ou diverticule de vessie</strong>.</li><li><strong>Résidu post-mictionnel > 100 mL</strong>.</li></ul>"},{"i":"fbe6b35df948","n":127,"o":"127-9","u":"Suivi et/ou pronostic","t":"Connaître les situations justifiant un avis spécialisé","q":"Quand faut-il référer un patient atteint d'hypertrophie bénigne de la prostate (HBP) pour un avis urologique en présence de symptômes du bas appareil urinaire (SBAU) semblant non liés à l'HBP ?","a":"<p>Un avis urologique est justifié en cas de :</p><ul><li><strong>Urgenturies isolées</strong>.</li><li><strong>Nycturie isolée</strong>.</li><li><strong>Incontinence urinaire</strong>.</li><li>Contexte clinique particulier (par exemple, <strong>maladie neurologique</strong>, <strong>sténose de l'urètre connue</strong>).</li></ul>"}]};